select dhc.id AS id, dhc.create_user_id AS createUserId, dhc.create_user_name AS createUserName, dhc.create_time AS createTime, dhc.update_user_id AS updateUserId, dhc.update_user_name AS updateUserName, dhc.update_time AS updateTime, dhc.version AS version, dhc.is_deleted AS isDeleted, dhc.hs_code AS hsCode, dhc.country AS country, dhc.description AS description, dhc.first_declare_unit AS firstDeclareUnit, dhc.declare_element AS declareElement, dhc.export_rebate_rate AS exportRebateRate, dhc.effective_date AS effectiveDate, dhc.expire_date AS expireDate, dhc.disabled AS disabled from dict_hs_code dhc where ${params.sqlMap.default} and dhc.is_deleted = FALSE and dhc.country = 'CN'
and dhc.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
dhc.create_time DESC

select dih.id AS id, dih.create_user_id AS createUserId, dih.create_user_name AS createUserName, dih.create_time AS createTime, dih.update_user_id AS updateUserId, dih.update_user_name AS updateUserName, dih.update_time AS updateTime, dih.version AS version, dih.is_deleted AS isDeleted, dih.hs_code AS hsCode, dih.country AS country, dih.description AS description, dih.first_declare_unit AS firstDeclareUnit, dih.second_declare_unit AS secondDeclareUnit, dih.declare_element AS declareElement, dih.supervision_conditions AS supervisionConditions, dih.mfn_rate AS mfnRate, dih.general_rate AS generalRate, dih.vat_rate AS vatRate, dih.consumption_tax_rate AS consumptionTaxRate, dih.export_rebate_rate AS exportRebateRate, dih.effective_date AS effectiveDate, dih.expire_date AS expireDate, dih.disabled AS disabled from dict_hs_code dih
${params.sqlMap.default} and dih.is_deleted = false and dih.country = 'BR'
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
dih.id desc
